/* Loading main into host memory (decision 0010).
 *
 * The tables below are generated by recomp.translate (work/recomp/image_info.c) from the
 * owner's main; the image bytes themselves are read from disk at start-up, never built in.
 */
#ifndef YW4LOAD_H
#define YW4LOAD_H

#include <stddef.h>
#include <stdint.h>

#include "yw4rt.h"

/* R_AARCH64_RELATIVE: *(base + offset) = base + addend */
typedef struct {
    uint64_t offset;
    int64_t addend;
} Yw4Relative;

/* ABS64 / GLOB_DAT / JUMP_SLOT: *(base + offset) = address of import + addend */
typedef struct {
    uint64_t offset;
    uint32_t import;
    uint32_t type;
    int64_t addend;
} Yw4SymReloc;

enum { YW4_IMPORT_FUNC, YW4_IMPORT_DATA, YW4_IMPORT_NULL };

typedef struct {
    const char *name;  /* mangled sdk symbol */
    uint32_t kind;     /* YW4_IMPORT_* */
} Yw4Import;

/* Generated */
extern const char yw4_image_sha256[65];
extern const uint64_t yw4_image_file_size, yw4_image_mem_size;
extern const Yw4Relative yw4_relative[];
extern const size_t yw4_nrelative;
extern const Yw4SymReloc yw4_symrelocs[];
extern const size_t yw4_nsymrelocs;
extern const Yw4Import yw4_imports[];
extern const size_t yw4_nimports;
extern const GuestFn yw4_import_fns[];  /* imp_<i>: calls yw4_import_call(ctx, i) */
extern const uint64_t yw4_entry_startup, yw4_entry_init, yw4_entry_main;  /* nninitStartup, DT_INIT, nnMain */

/* Runtime */
#define YW4_PREFERRED_BASE 0x7100000000ull  /* where main sits on the Switch */
#define YW4_STACK_BASE 0x7000000000ull      /* guest stacks: also inside the 39-bit space games may assume */
#define YW4_IMPORT_STRIDE 16                /* bytes per function-import stub address */

extern uint64_t yw4_import_base;            /* function imports live at base + 16 * index */

/* Zeroed read/write memory, at `want` if that range is free (0 = anywhere), else anywhere. */
void *yw4_reserve(uint64_t want, size_t size);

/* Reads, verifies (size + SHA-256) and relocates main. Returns 0 on success; prints why not. */
int yw4_load_image(const char *path);

/* Called by imp_<i>: runs the native implementation of import i, or stops with its name. */
void yw4_import_call(CPUState *ctx, uint32_t index);

/* SHA-256 of a buffer as 64 lowercase hex digits + NUL. */
void yw4_sha256_hex(const uint8_t *data, size_t len, char out[65]);

#endif
